INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(4801, 'Deuteronomy 11:18', 'Deuteronomy', 11, 18, '&nbsp;دا حُکمونه ياد ساتئ او په ذهن کښې يې وساتئ. دا په خپلو مټو او خپلو تندو باندې وتړئ چې ستاسو دپاره د يادېدو د يوې نښې په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4802, 'Deuteronomy 11:19', 'Deuteronomy', 11, 19, '&nbsp;دا په خپلو ماشومانو زده کړئ. چې تاسو په کور کښې يئ او يا په لاره روان يئ، چې تاسو څملئ او يا پاڅئ نو د دې په حقله د هغوئ سره خبرې کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4803, 'Deuteronomy 11:20', 'Deuteronomy', 11, 20, '&nbsp;دا د خپلو کورونو په درشلو او د خپلو ښارونو په دروازو وليکئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4804, 'Deuteronomy 11:21', 'Deuteronomy', 11, 21, '&nbsp;نو تاسو او ستاسو بچى به په هغه مُلک کښې يو اوږد عُمر تېر کړى چې مالِک خُدائ ستاسو د پلار نيکۀ سره د هغې د ورکولو وعده کړې ده. تر څو چې زمکه او آسمان وى نو تاسو به هلته اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4805, 'Deuteronomy 11:22', 'Deuteronomy', 11, 22, '&nbsp;ما چې کوم حُکمونه درکړى دى په هغې باندې په ايماندارۍ سره عمل کوئ يعنې، مالِک خُدائ د خپل خُدائ پاک سره مينه کوئ، د هغۀ په لاره سم روان اوسئ او د هغۀ نه مۀ لرې کېږئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4806, 'Deuteronomy 11:23', 'Deuteronomy', 11, 23, '&nbsp;نو چې تاسو مخ په وړاندې ځئ نو هغه به هغه ټول قومونه وشړى او تاسو به هغه مُلک قبضه کړئ کوم چې د هغه قومونو دے چې ستاسو نه لوئ او طاقتور دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4807, 'Deuteronomy 11:24', 'Deuteronomy', 11, 24, '&nbsp;تاسو چې چرته هم قدم ږدئ، نو هغه زمکه به ستاسو وى. ستاسو علاقه به د بيابان نه تر لبنان پورې، د فرات د سيند نه واخله د مديترانى د سمندر پورې خوره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4808, 'Deuteronomy 11:25', 'Deuteronomy', 11, 25, '&nbsp;په هغه مُلک کښې چې تاسو چرته هم ځئ، مالِک خُدائ ستاسو خُدائ پاک به هغه خلق ستاسو نه ويروى لکه څنګه چې هغۀ وعده کړې ده او هيڅ څوک به هم ستاسو په مخکښې نۀ شى ودرېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4809, 'Deuteronomy 11:26', 'Deuteronomy', 11, 26, '&nbsp;ګورئ، زۀ نن تاسو خپلې خوښې ته پرېږدم چې برکت غواړئ او کۀ لعنت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4810, 'Deuteronomy 11:27', 'Deuteronomy', 11, 27, '&nbsp;برکت به په دې کښې وى، چې د مالِک خُدائ ستاسو خُدائ پاک په هغه حُکمونو عمل کوئ چې نن يې زۀ درکوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4811, 'Deuteronomy 11:28', 'Deuteronomy', 11, 28, '&nbsp;لعنت به په دې کښې وى، چې تاسو د دې حُکمونو نافرمانى وکړئ او د هغه معبودانو عبادت ته واوړئ چې تاسو مخکښې نۀ دى پېژندلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4812, 'Deuteronomy 11:29', 'Deuteronomy', 11, 29, '&nbsp;کله چې مالِک خُدائ تاسو هغه مُلک ته راولى کوم چې تاسو قبضه کوئ، نو د برکت آواز به تاسو د ګِرزيم غر نه وکړئ او د لعنت آواز به د عيبال غر نه وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4813, 'Deuteronomy 11:30', 'Deuteronomy', 11, 30, '&nbsp;دا دوه غرونه د کنعانيانو په علاقه کښې د اُردن سيند نمرپرېواتۀ طرف ته دى، کنعانيان د اُردن په مېدان کښې اوسيږى، چې جِلجال ښار ته نزدې دے او د موره مقدسو ونو نه لرې نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4814, 'Deuteronomy 11:31', 'Deuteronomy', 11, 31, '&nbsp;زر به تاسو د اُردن سيند نه واوړئ او هغه مُلک به قبضه کړئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى. کله چې هغه مُلک ونيسئ او په کښې اوسېږئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4815, 'Deuteronomy 11:32', 'Deuteronomy', 11, 32, '&nbsp;نو ګورئ، په هغه ټولو حُکمونو به عمل کوئ کوم چې نن زۀ درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4816, 'Deuteronomy 12:1', 'Deuteronomy', 12, 1, '&nbsp;موسىٰ وفرمائيل چې، ”دا هغه حُکمونه دى چې تاسو به په هغه مُلک کښې پرې عمل کوئ چې مالِک خُدائ، ستاسو د پلار نيکۀ خُدائ پاک يې درکوى. چې تاسو ژوندى يئ نو خامخا به ورباندې عمل کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4817, 'Deuteronomy 12:2', 'Deuteronomy', 12, 2, '&nbsp;کوم مُلک چې تاسو نيسئ په هغې کښې هغه ټول ځايونه تباه کړئ چرته چې هغه خلق په لوړو غرونو، په غونډو او د لويو شنو ونو لاندې د خپلو معبودانو عبادت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4818, 'Deuteronomy 12:3', 'Deuteronomy', 12, 3, '&nbsp;د هغوئ د قربانۍ ځايونه وران کړئ او د هغوئ د کاڼو مقدسې ستنې ټوټې ټوټې کړئ. د هغوئ د اشيرې بُت نښې وسوزوئ او د هغوئ بُتان ټوټې ټوټې کړئ او د هغه ځايونو نه د هغوئ د بُتانو نوم نشان ختم کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4819, 'Deuteronomy 12:4', 'Deuteronomy', 12, 4, '&nbsp;د مالِک خُدائ د خپل خُدائ پاک عبادت هغه شان مۀ کوئ لکه څنګه يې چې هغوئ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4820, 'Deuteronomy 12:5', 'Deuteronomy', 12, 5, '&nbsp;خو مالِک خُدائ به د ستاسو ټولو قبيلو د علاقې نه يو ځائ خوښ کړى، هلته به خلق د هغۀ حضور ته راځى او د هغۀ عبادت به کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4821, 'Deuteronomy 12:6', 'Deuteronomy', 12, 6, '&nbsp;هلته به خپلې سوزېدونکې نذرانې او نورې قربانۍ، خپله لسمه حِصه او مقدسې نذرانې، خپلې منښتې، خپلې رضاکارانه نذرانې او د خپلو څاروو او ګډو وړومبى پېدا شوى بچى پېش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4822, 'Deuteronomy 12:7', 'Deuteronomy', 12, 7, '&nbsp;هلته، د مالِک خُدائ ستاسو خُدائ پاک په حضور کښې تاسو او ستاسو خاندان به خوراک کوئ او د هغه هر څيز نه به پوره خوند اخلئ چې تاسو د هغې دپاره محنت کړے وى. ځکه چې مالِک خُدائ ستاسو خُدائ پاک تاسو له برکت درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4823, 'Deuteronomy 12:8', 'Deuteronomy', 12, 8, '&nbsp;کله چې هغه وخت راشى، نو تاسو چې داسې کارونه ونۀ کړئ لکه چې دلته يې کوئ. تر اوسه پورې چې تاسو ته څۀ ښۀ ښکارېدل نو هم هغه شان مو کول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4824, 'Deuteronomy 12:9', 'Deuteronomy', 12, 9, '&nbsp;ځکه چې تاسو ته هغه ميراث لا نۀ دے مِلاو شوے چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى، چې هلته به تاسو په امن کښې اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4825, 'Deuteronomy 12:10', 'Deuteronomy', 12, 10, '&nbsp;کله چې تاسو د اُردن سيند نه واوړئ، نو مالِک خُدائ به هغه مُلک تاسو له په ميراث کښې درکړى. هغه به تاسو د خپلو ټولو دشمنانو نه په حِفاظت کښې وساتى او تاسو به په امن کښې اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4826, 'Deuteronomy 12:11', 'Deuteronomy', 12, 11, '&nbsp;مالِک خُدائ به يو ځائ خوښ کړى چرته به چې د هغۀ عبادت کيږى او هلته به تاسو هغۀ له هغه هر څۀ راوړئ چې ما يې حُکم درکړے دے، يعنې خپلې سوزېدونکې نذرانې او خپلې نورې قربانۍ، ستاسو لسمه حِصه او منښتې او هغه خاص نذرانې چې تاسو د مالِک خُدائ سره د هغې وعده کړې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4827, 'Deuteronomy 12:12', 'Deuteronomy', 12, 12, '&nbsp;د خپلو بچو سره، خپلو نوکرانو او د ليويانو سره چې ستاسو په ښارونو کښې اوسيږى، هلته د هغۀ په حضور کښې خوشحالى کوئ، ياد لرئ چې د ليويانو به په زمکه کښې هيڅ ميراث نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4828, 'Deuteronomy 12:13', 'Deuteronomy', 12, 13, '&nbsp;تاسو به خپلې نذرانې هلته نۀ پېش کوئ چې چرته ستاسو خوښه وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4829, 'Deuteronomy 12:14', 'Deuteronomy', 12, 14, '&nbsp;تاسو به خپلې نذرانې صِرف په هغه يو ځائ کښې پېش کوئ چې مالِک خُدائ به يې ستاسو د يوې قبيلې په علاقه کښې خوښ کړى. صِرف هلته به تاسو خپلې سوزېدونکې نذرانې او نور هغه ټول کارونه کوئ چې ما يې تاسو له حُکم درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4830, 'Deuteronomy 12:15', 'Deuteronomy', 12, 15, '&nbsp;چې چرته تاسو اوسېږئ نو تاسو هلته خپل ځناور حلالولے او خوړلے شئ. مالِک خُدائ چې څومره ډېر درکوى نو هغه خوړلے شئ. تاسو ټول کۀ پاک يئ يا ناپاک، هغه خوړلے شئ، لکه څنګه چې تاسو هوسۍ يا د غرڅۍ غوښه خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4831, 'Deuteronomy 12:16', 'Deuteronomy', 12, 16, '&nbsp;خو تاسو به د هغې وينه نۀ څښئ، تاسو به خامخا د هغې وينه لکه د اوبو په زمکه تويَوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4832, 'Deuteronomy 12:17', 'Deuteronomy', 12, 17, '&nbsp;څۀ چې تاسو مالِک خُدائ ته پېش کوئ د هغې نه به هيڅ يو څيز په هغه ځايونو کښې نۀ شى خوړلے چرته چې تاسو اوسېږئ، نۀ ستاسو د غلې لسمه حِصه، نۀ خپل مے، نۀ د زيتُونو تېل، نۀ ستاسو د څاروو او ګډو وړومبے پېدا شوے بچے، نۀ د هغه تُحفې نه چې تاسو يې د مالِک خُدائ سره وعده کړې وى، نۀ ستاسو رضاکارانه نذرانې او نۀ نورې نذرانې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4833, 'Deuteronomy 12:18', 'Deuteronomy', 12, 18, '&nbsp;تاسو او ستاسو بچى به، سره د ستاسو نوکرانو او د ليويانو چې ستاسو په ښارونو کښې اوسيږى، دا نذرانې به صِرف د مالِک خُدائ ستاسو خُدائ پاک په حضور کښې خورئ، صِرف د عبادت په هغه يو ځائ کښې کوم چې مالِک خُدائ ستاسو خُدائ پاک خوښ کړے وى. او تاسو به هلته په هغه هر څۀ باندې خوشحاله يئ کوم چې تاسو کړى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4834, 'Deuteronomy 12:19', 'Deuteronomy', 12, 19, '&nbsp;ګورئ، چې تر کومې پورې تاسو په خپل مُلک کښې اوسېږئ نو چې ليويان هم هېر نۀ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4835, 'Deuteronomy 12:20', 'Deuteronomy', 12, 20, '&nbsp;کله چې مالِک خُدائ ستاسو خُدائ پاک ستاسو علاقه لويه کړى، لکه څنګه چې هغۀ وعده کړې ده نو بيا چې کله هم تاسو غواړئ نو هلته غوښه خوړے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4836, 'Deuteronomy 12:21', 'Deuteronomy', 12, 21, '&nbsp;د عبادت هغه يو ځائ کۀ ډېر لرې وى، نو بيا چې ستاسو خوښه وى، نو هغه څاروے يا ګډ حلالولے شئ کوم چې مالِک خُدائ درکړے وى او تاسو هغه غوښه په کور کښې خوړلے شئ، لکه څنګه چې ما تاسو ته وئيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4837, 'Deuteronomy 12:22', 'Deuteronomy', 12, 22, '&nbsp;هر څوک چې پاک وى يا ناپاک، نو هغه دا غوښه خوړلے شى، لکه څنګه چې هغه د هوسۍ يا غرڅۍ غوښه خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4838, 'Deuteronomy 12:23', 'Deuteronomy', 12, 23, '&nbsp;صِرف هغه غوښه مۀ خورئ چې وينه لا په کښې وى، ځکه چې په وينه کښې ژوندون وى، نو تاسو د غوښې سره ژوندون مۀ خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4839, 'Deuteronomy 12:24', 'Deuteronomy', 12, 24, '&nbsp;وينه د خوراک دپاره مۀ استعمالوئ، بلکې د اوبو په شان يې په زمکه تويَوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4840, 'Deuteronomy 12:25', 'Deuteronomy', 12, 25, '&nbsp;کۀ تاسو دا حُکم ومنئ، نو مالِک خُدائ به خوشحاله شى او ستاسو او ستاسو د بچو به هر کار سم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4841, 'Deuteronomy 12:26', 'Deuteronomy', 12, 26, '&nbsp;خپلې نذرانې او هغه تُحفې چې تاسو يې د مالِک خُدائ سره وعده کړې وى د عبادت هغه يو ځائ ته راوړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4842, 'Deuteronomy 12:27', 'Deuteronomy', 12, 27, '&nbsp;هلته هغه نذرانې پېش کوئ کومې چې د مالِک خُدائ په قربان‌ګاه باندې پوره سوزولے شى. هغه نذرانې هم پېش کوئ چې تاسو د هغې غوښه خورئ او وينه يې په قربان‌ګاه باندې تويَوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4843, 'Deuteronomy 12:28', 'Deuteronomy', 12, 28, '&nbsp;په هغه هر څۀ باندې په وفادارۍ سره عمل کوئ چې ما يې حُکم درکړے دے، نو ستاسو او ستاسو د اولاد به د همېشه دپاره هر کار سم وى، ځکه چې تاسو به هغه کار کوئ چې کوم صحيح وى او په کوم باندې چې مالِک خُدائ ستاسو خُدائ پاک خوشحاليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4844, 'Deuteronomy 12:29', 'Deuteronomy', 12, 29, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک به هغه قومونه تباه کړى چې تاسو د هغوئ مُلک ونيسئ، نو تاسو به هغه مُلک قبضه کړئ او هلته به اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4845, 'Deuteronomy 12:30', 'Deuteronomy', 12, 30, '&nbsp;پام کوئ چې کله مالِک خُدائ هغه قومونه تباه کړى، نو چې د هغوئ په عبادت او رسمونو کښې راګېر نۀ شئ چې هغه ومنئ، ځکه هغه به ستاسو دپاره يو دام وى. د دې معلومولو کوشش مۀ کوئ چې هغوئ د خپلو معبودانو عبادت څنګه کوى، چې تاسو هم هغه شان عبادت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4846, 'Deuteronomy 12:31', 'Deuteronomy', 12, 31, '&nbsp;د مالِک خُدائ د خپل خُدائ پاک عبادت هغه شان مۀ کوئ چې څنګه هغوئ د خپلو معبودانو عبادت کوى، ځکه چې هغوئ د خپلو معبودانو په عبادت کښې ټول هغه حرام کارونه کوى چې مالِک خُدائ ترې نه نفرت کوى. تر دې پورې چې هغوئ په اور کښې خپل بچى هم قربانى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4847, 'Deuteronomy 12:32', 'Deuteronomy', 12, 32, '&nbsp;هغه هر څۀ کوئ چې ما يې حُکم درکړے دے، په دې کښې مۀ څۀ کموئ او مۀ څۀ زياتوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4848, 'Deuteronomy 13:1', 'Deuteronomy', 13, 1, '&nbsp;کېدے شى چې پېغمبران يا د خوبونو تعبير ورکوونکى د يوې معجزې يا د يوې عجيبه نښې وعده وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4849, 'Deuteronomy 13:2', 'Deuteronomy', 13, 2, '&nbsp;او کۀ هغه پېشګوئې شوې نښې يا معجزې څرګندې شى، او کۀ هغوئ وائى، چې نورو معبودانو ته راواوړئ کوم چې تاسو نۀ دى پېژندلى او د هغوئ عبادت وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4850, 'Deuteronomy 13:3', 'Deuteronomy', 13, 3, '&nbsp;نو هغه پېغمبرانو يا د خوبونو تعبير ورکوونکو ته غوږ مۀ نيسئ. مالِک خُدائ ستاسو خُدائ پاک تاسو معلوموى چې تاسو د مالِک خُدائ سره د زړۀ د اخلاصه او د خپل ټول روح سره مينه کوئ او کۀ نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4851, 'Deuteronomy 13:4', 'Deuteronomy', 13, 4, '&nbsp;د مالِک خُدائ تابعدارى کوئ او د هغۀ درناوے کوئ، د هغۀ اِطاعت کوئ او د هغۀ حُکمونه منئ، د هغۀ عبادت کوئ او د هغۀ وفادار اوسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4852, 'Deuteronomy 13:5', 'Deuteronomy', 13, 5, '&nbsp;خو هغه د خوبونو تعبير ورکوونکى يا پېغمبران ووژنئ چې تاسو ته وائى چې د مالِک خُدائ خِلاف بغاوت وکړئ، چا چې د مِصر نه راوويستلئ، چرته چې تاسو غلامان وئ. داسې خلق تاسو د هغه لارې نه اړوى په کومه باندې چې مالِک خُدائ تاسو له د تلو حُکم درکړے دے. هغوئ دې خامخا ووژلے شى، چې خپل ځانونه د دې بد عمل نه خلاص کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4853, 'Deuteronomy 13:6', 'Deuteronomy', 13, 6, '&nbsp;کۀ ستاسو ورور، زوئ، لور، يا په تاسو ګرانه ښځه، يا ستاسو نزدې دوست هم تاسو ته پټ پټ وائى چې د نورو معبودانو عبادت وکړئ، هغه معبودان چې تاسو او ستاسو پلار نيکۀ يې هيڅکله هم عبادت نۀ دے کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4854, 'Deuteronomy 13:7', 'Deuteronomy', 13, 7, '&nbsp;کېدے شى چې هغوئ تاسو ته ووائى چې د هغه خلقو د معبودانو عبادت وکړئ کوم چې ستاسو سره نزدې اوسيږى يا د هغه خلقو د معبودانو کوم چې ستاسو نه لرې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4855, 'Deuteronomy 13:8', 'Deuteronomy', 13, 8, '&nbsp;خو هغوئ ته توجو مۀ ورکړئ او مۀ ورته غوږ نيسئ. په هغوئ باندې هيڅ رحم يا ترس مۀ کوئ او د هغوئ خبره مۀ پټوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4856, 'Deuteronomy 13:9', 'Deuteronomy', 13, 9, '&nbsp;هغوئ ووژنئ. وړومبے کاڼے تاسو ورګزار کړئ او بيا نور خلق ورپرېږدئ چې سنګسار يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4857, 'Deuteronomy 13:10', 'Deuteronomy', 13, 10, '&nbsp;سنګسار يې کړئ چې مړ شى. هغوئ کوشش کولو چې تاسو د مالِک خُدائ ستاسو خُدائ پاک نه تاسو واړوى، کوم چې تاسو د مِصر مُلک نه راوويستلئ، چرته چې تاسو غلامان وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4858, 'Deuteronomy 13:11', 'Deuteronomy', 13, 11, '&nbsp;نو د بنى اِسرائيلو ټول خلق به خبر شى چې څۀ وشول، هغوئ به ويريږى او بيا به هيڅکله هيڅ څوک هم داسې بد عمل ونۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4859, 'Deuteronomy 13:12', 'Deuteronomy', 13, 12, '&nbsp;کله چې تاسو په هغه ښارونو کښې اوسېږئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى، نو کېدے شى چې تاسو خبر شئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4860, 'Deuteronomy 13:13', 'Deuteronomy', 13, 13, '&nbsp;چې ستاسو د قوم څۀ لوفرانو خلقو د خپل ښار خلق بې‌لارې کړى دى چې د هغه معبودانو عبادت وکړى چې تاسو يې کله هم د دې نه مخکښې عبادت نۀ دے کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4861, 'Deuteronomy 13:14', 'Deuteronomy', 13, 14, '&nbsp;کۀ تاسو داسې يو افواه واورئ، نو د هغې پوره معلومات وکړئ، نو کۀ په رښتيا دا بد عمل شوے وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4862, 'Deuteronomy 13:15', 'Deuteronomy', 13, 15, '&nbsp;نو بيا د هغه ښار ټول خلق او د هغوئ ټول ځناور هم ووژنئ. هغه ښار پوره تباه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4863, 'Deuteronomy 13:16', 'Deuteronomy', 13, 16, '&nbsp;کوم خلق چې هلته اوسيږى د هغوئ ټول مال هم راوړئ او د ښار په مرکزى ځائ کښې يې ډېرے کړئ. بيا هغه ښار او چې په هغې کښې څۀ هم وى مالِک خُدائ ستاسو خُدائ پاک ته د نذرانې په توګه وسوزوئ. دا ښار به د همېشه دپاره کنډر پاتې کيږى او دا به هيڅکله بيا آباد نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4864, 'Deuteronomy 14:1', 'Deuteronomy', 14, 1, '&nbsp;تاسو د مالِک خُدائ د خپل خُدائ پاک خلق يئ. نو کله چې تاسو په مړى باندې غم کوئ، نو خپل ځانونه د نورو خلقو په شان مۀ زخمى کوئ يا د تندى نه بره وېښتۀ مۀ کلوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4865, 'Deuteronomy 14:2', 'Deuteronomy', 14, 2, '&nbsp;تاسو د مالِک خُدائ د خپل خُدائ پاک خلق يئ، په زمکه باندې چې څومره خلق اوسيږى په هغوئ ټولو کښې يې تاسو د دې دپاره خوښ کړئ چې د هغۀ خپل خاص خلق اوسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4866, 'Deuteronomy 14:3', 'Deuteronomy', 14, 3, '&nbsp;هيڅ يو حرام څيز مۀ خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4867, 'Deuteronomy 14:4', 'Deuteronomy', 14, 4, '&nbsp;تاسو دا ځناور خوړے شئ، څاروى، ګډې، چېلۍ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4868, 'Deuteronomy 14:5', 'Deuteronomy', 14, 5, '&nbsp;هوسۍ، ځنګلى ګډې، ځنګلى چېلۍ او غرڅۍ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4869, 'Deuteronomy 14:6', 'Deuteronomy', 14, 6, '&nbsp;هغه ټول ځناور چې سومونه يې په مينځ بېل وى او بيا بيا شخوند وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4870, 'Deuteronomy 14:7', 'Deuteronomy', 14, 7, '&nbsp;خو صِرف هغه ځناور به حلال وى چې سومونه يې په مينځ بېل وى او بيا بيا شخوند هم وهى. تاسو اوښ، سوه، يا ځنګلى سوه نۀ شئ خوړلے. دا به خامخا حرام ګڼلے شى، ځکه چې دا بيا بيا شخوند وهى خو سومونه يې په مينځ بېل نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4871, 'Deuteronomy 14:8', 'Deuteronomy', 14, 8, '&nbsp;خنزيران مۀ خورئ، دا به خامخا حرام ګڼلے شى، کۀ څۀ هم سومونه يې په مينځ بېل دى خو دا بيا بيا شخوند نۀ وهى. دا ځناور مۀ خورئ يا کۀ مړ وى لاس به هم نۀ وروړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4872, 'Deuteronomy 14:9', 'Deuteronomy', 14, 9, '&nbsp;تاسو هغه هر قِسم کبان خوړلے شئ کوم چې وزر او په څرمن پترى لرى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4873, 'Deuteronomy 14:10', 'Deuteronomy', 14, 10, '&nbsp;خو داسې د اوبو بل هر يو څيز چې وزر او په څرمن پترى نۀ لرى هغه به نۀ شئ خوړلے، دا به خامخا حرام ګڼلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4874, 'Deuteronomy 14:11', 'Deuteronomy', 14, 11, '&nbsp;تاسو حلال مارغان خوړلے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4875, 'Deuteronomy 14:19', 'Deuteronomy', 14, 19, '&nbsp;ټول الوتونکى حشرات ناپاک دى، هغه مۀ خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4876, 'Deuteronomy 14:20', 'Deuteronomy', 14, 20, '&nbsp;خو تاسو حلال حشرات خوړلے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4877, 'Deuteronomy 14:21', 'Deuteronomy', 14, 21, '&nbsp;هغه يو ځناور هم مۀ خورئ، چې په خپل مرګ مړ وى. تاسو سره چې کوم مسافر اوسيږى هغوئ ته دا ورکولے شئ چې وې خورى، يا دا په نورو مسافرو باندې خرڅولے شئ. خو تاسو د مالِک خُدائ د خپل خُدائ پاک يئ او تاسو د هغۀ خلق يئ. ګډُورے يا د چېلۍ بچے د خپلې مور په پيو کښې مۀ پخوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4878, 'Deuteronomy 14:22', 'Deuteronomy', 14, 22, '&nbsp;تاسو خامخا لسمه برخه ورکوئ، د خپل هر فصل لسمه حِصه چې تاسو يې هر کال رېبئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4879, 'Deuteronomy 14:23', 'Deuteronomy', 14, 23, '&nbsp;بيا هغه يو ځائ ته ځئ کوم چې مالِک خُدائ ستاسو خُدائ پاک د خپل عبادت دپاره خوښ کړے دے او هلته د هغۀ په حضور کښې د خپل فصل، ميو او د زيتُونو تېلو او ستاسو د وړومبى پېدا شوى څاروو او ګډو لسمه برخه خورئ. دا د دې دپاره کوئ چې تاسو د مالِک خُدائ خپل خُدائ پاک نه د همېشه دپاره يرېدل زده کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4880, 'Deuteronomy 14:24', 'Deuteronomy', 14, 24, '&nbsp;کۀ د عبادت ځائ ستاسو د کور نه ډېر لرې وى چې هلته د خپل پېداوار لسمه برخه يوسئ چې مالِک خُدائ د هغې برکت درکړے دے، نو بيا داسې وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4881, 'Deuteronomy 14:25', 'Deuteronomy', 14, 25, '&nbsp;خپل پېداوار خرڅ کړئ او د دې پېسې د ځان سره د عبادت هغه يو ځائ ته يوسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4882, 'Deuteronomy 14:26', 'Deuteronomy', 14, 26, '&nbsp;چې ستاسو زړۀ څۀ غواړى لکه غټه غوښه، نرۍ غوښه، مے يا شراب، نو په دې پېسو يې واخلئ. او هلته، د مالِک خُدائ ستاسو خُدائ پاک په حضور کښې يې د خپل خاندان سره خورئ او خوشحالى وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4883, 'Deuteronomy 14:27', 'Deuteronomy', 14, 27, '&nbsp;هغه ليويان مۀ هېروئ چې ستاسو په ښارونو کښې اوسيږى، ځکه چې د هغوئ خپل هيڅ جائيداد نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4884, 'Deuteronomy 14:28', 'Deuteronomy', 14, 28, '&nbsp;د هر درېم کال په آخر کښې د خپلو ټولو فصلونو لسمه برخه راوړئ او په خپلو ښارونو کښې يې ذخيره کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4885, 'Deuteronomy 14:29', 'Deuteronomy', 14, 29, '&nbsp;دا خوراک د ليويانو دپاره دے، ځکه چې د هغوئ خپل جائيداد نشته او ورسره د هغه مسافرو دپاره، يتيمانو او کونډو دپاره دے چې ستاسو په ښارونو کښې اوسيږى. هغوئ ټول دې راځى او د خپل ضرورت څيزونه دې ترې نه اخلى. هم دغه شان کوئ او مالِک خُدائ ستاسو خُدائ پاک به تاسو له ستاسو په هر څۀ کښې برکت درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4886, 'Deuteronomy 15:1', 'Deuteronomy', 15, 1, '&nbsp;د هر اوؤم کال په آخر کښې تاسو قرضونه معاف کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4887, 'Deuteronomy 15:2', 'Deuteronomy', 15, 2, '&nbsp;دا هغه څۀ دى چې تاسو به يې خامخا کوئ. هر چا چې خپلو بنى اِسرائيلو له قرض ورکړى وى نو هغه به ورته معاف کوى، هغه به د خپل ګاونډى يا د هغۀ د خپلوانو نه دا قرض واپس نۀ اخلى، مالِک خُدائ په خپله دا اِعلان کړے دے چې قرض معاف شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4888, 'Deuteronomy 15:3', 'Deuteronomy', 15, 3, '&nbsp;چې په يو مسافر باندې ستاسو قرض وى نو د هغۀ نه پېسې اخستے شئ، خو چې ستاسو په بنى اِسرائيلو قرض وى نو د هغوئ نه به يې نۀ اخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4889, 'Deuteronomy 15:4', 'Deuteronomy', 15, 4, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک به تاسو له په هغه مُلک کښې برکت درکړى کوم چې تاسو له درکوى. ستاسو د خلقو نه به هيڅ څوک هم غريب نۀ وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4890, 'Deuteronomy 15:5', 'Deuteronomy', 15, 5, '&nbsp;کۀ تاسو د هغۀ فرمانبردارى کوئ او هغه هر څۀ پوره پوره ومنئ چې نن يې زۀ حُکم درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4891, 'Deuteronomy 15:6', 'Deuteronomy', 15, 6, '&nbsp;نو مالِک خُدائ به تاسو له برکت درکړى، لکه څنګه چې هغۀ وعده کړې ده. تاسو به ډېرو قومونو له قرض ورکړئ، خو تاسو به د هيچا نه قرض نۀ اخلئ، ستاسو په قبضه کښې به ډېر قومونه وى، خو تاسو به د هيچا په قبضه کښې نۀ يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4892, 'Deuteronomy 15:7', 'Deuteronomy', 15, 7, '&nbsp;کوم مُلک چې مالِک خُدائ ستاسو خُدائ پاک تاسو له درکوى کۀ د هغې په ښارونو کښې ستاسو خپل يو اِسرائيلے محتاج وى، نو خپل زړۀ مۀ سختوئ او د هغۀ مدد کولو نه لاس مۀ نيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4893, 'Deuteronomy 15:8', 'Deuteronomy', 15, 8, '&nbsp;خو سخيان اوسېږئ او چې څومره پېسو ته يې ضرورت وى نو هغه هومره قرض ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4894, 'Deuteronomy 15:9', 'Deuteronomy', 15, 9, '&nbsp;هغۀ ته د څۀ څيز قرض ورکولو نه په دې وجه اِنکار مۀ کوئ چې د قرضونو د معاف کولو کال نزدې دے. داسې بد سوچونه خپل ذهن ته مۀ راولئ. کۀ تاسو خپل ورور له قرض ورنۀ کړئ نو هغه به مالِک خُدائ ته ستاسو خِلاف فرياد وکړى او ګناه به ستاسو په غاړه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4895, 'Deuteronomy 15:10', 'Deuteronomy', 15, 10, '&nbsp;هغۀ ته چې د څۀ څيز ضرورت وى نو په خوشحالۍ سره او د زړۀ د اخلاصه يې ورکړئ، نو مالِک خُدائ به تاسو له په هر کار کښې برکت درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4896, 'Deuteronomy 15:11', 'Deuteronomy', 15, 11, '&nbsp;په مخ د زمکې به همېشه غريبانان خلق موجود وى، نو زۀ تاسو له حُکم درکوم چې د خپلو بنى اِسرائيلو د مدد نه لاس مۀ نيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4897, 'Deuteronomy 15:12', 'Deuteronomy', 15, 12, '&nbsp;کۀ يو عبرانے سړے يا ښځه خپل ځان په تاسو باندې د غلام يا وينځې په توګه خرڅ کړى، نو چې هغوئ شپږ کاله ستاسو خِدمت وکړى نو د هغې نه پس هغوئ آزاد کړئ. کله چې اوؤم کال راشى، نو هغوئ به خامخا پرېږدئ چې لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4898, 'Deuteronomy 15:13', 'Deuteronomy', 15, 13, '&nbsp;کله چې تاسو هغوئ آزادوئ، نو تش لاس يې مۀ لېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4899, 'Deuteronomy 15:14', 'Deuteronomy', 15, 14, '&nbsp;چې مالِک خُدائ تاسو له کوم برکت درکړې وى نو د خپلو ګډو، غلې او د انګورو لنګرۍ نه ډېر څۀ ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4900, 'Deuteronomy 15:15', 'Deuteronomy', 15, 15, '&nbsp;هغه راپه ياد کړئ چې تاسو په مِصر کښې غلامان وئ او مالِک خُدائ خپل خُدائ پاک تاسو آزاد کړئ، نو ځکه زۀ تاسو له دا حُکم درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');